mapper.select:
SELECT 
FROM sys_file_folder
WHERE space = #{space}
  AND deleted_at IS NULL

    AND parent_id IS NULL
    AND parent_id = #{parentId}

AND owner_id = #{ownerId}
ORDER BY name

WITH RECURSIVE sub AS (
    SELECT id, parent_id FROM sys_file_folder
    WHERE id = #{rootId} AND deleted_at IS NULL AND tenant_id = #{tenantId}
    UNION ALL
    SELECT f.id, f.parent_id FROM sys_file_folder f
    JOIN sub ON f.parent_id = sub.id
    WHERE f.deleted_at IS NULL AND f.tenant_id = #{tenantId}
)
SELECT id FROM sub

WITH RECURSIVE sub AS (
    SELECT id, parent_id FROM sys_file_folder
    WHERE id = #{rootId} AND deleted_at IS NOT NULL AND tenant_id = #{tenantId}
    UNION ALL
    SELECT f.id, f.parent_id FROM sys_file_folder f
    JOIN sub ON f.parent_id = sub.id
    WHERE f.deleted_at IS NOT NULL AND f.tenant_id = #{tenantId}
)
SELECT id FROM sub

