UPDATE sys_file_folder SET deleted_at = now()
WHERE deleted_at IS NULL AND id IN
#{i}

UPDATE sys_file_folder SET deleted_at = NULL
WHERE deleted_at IS NOT NULL AND id IN
#{i}

UPDATE sys_file_folder SET depth = depth + #{delta}
WHERE id IN
#{i}

mapper.select:
SELECT 
FROM sys_file_folder
WHERE deleted_at IS NOT NULL
  AND deleted_at < #{threshold}
ORDER BY deleted_at ASC
LIMIT #{limit}
